using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Markup;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using HdrPilot;
class VisibilityCheck{
 static void Pump(){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 static T Find<T>(DependencyObject root)where T:DependencyObject{if(root is T)return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var t=Find<T>(VisualTreeHelper.GetChild(root,i));if(t!=null)return t;}return null;}
 [STAThread]static void Main(string[] a){new Application();Window resources;using(var f=File.OpenRead(Path.Combine(a[0],"source","Main.xaml")))resources=(Window)XamlReader.Load(f);var p=new StackPanel{Margin=new Thickness(20)};var w=new Window{Width=900,Height=290,Content=p,Resources=resources.Resources,Background=new SolidColorBrush(Color.FromRgb(20,27,35)),Left=-10000,Top=-10000,ShowActivated=false};var e=new Expander{Header="Add-on opzionali · RenoDX HDR, MFG e shader",Content=new TextBlock{Text="RenoDX HDR     •     MFG Unlock     •     Shader ReShade",Foreground=Brushes.White,Margin=new Thickness(12)},Margin=new Thickness(0,0,0,14)};p.Children.Add(e);p.Children.Add(new Expander{Header="Loader per altre mod · avanzato",Content=new TextBlock{Text="ASI Loader / REFramework / UE4SS"}});w.Show();Pump();var b=Find<ToggleButton>(e);if(b==null||b.ActualHeight<48)throw new Exception("header not accessible");b.IsChecked=true;Pump();if(!e.IsExpanded)throw new Exception("open failed");b.IsChecked=false;Pump();if(e.IsExpanded)throw new Exception("close failed");var bitmap=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(w);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(Path.Combine(a[0],"visibility-preview.png")))png.Save(f);w.Close();if(LegacyHdr.Present(null))throw new Exception("empty legacy filter visible");File.WriteAllText(Path.Combine(a[0],"visibility-tests-passed.txt"),"PASS: XAML parsing, full-width expandable headers, 48px target, open/close binding and absent legacy filter.");}
}
